define({"topics":[{"title":"Electrical Safety","shortdesc":"<p class=\"shortdesc\">You must follow all recommended safety procedures when servicing and working near energy sources.<\/p>","href":"r_ElectricalSafety_88.html","attributes":{"data-id":"id_2001693"},"menu":{"hasChildren":false},"tocID":"id_2001693-d46e304971","topics":[]},{"title":"Shutting down the host computer","shortdesc":"<p class=\"shortdesc\">Shutting down the host computer shuts down the system safely and turns off the power to the host computer.<\/p>","href":"t_ShuttingDownHostComputer_88.html","attributes":{"data-id":"id_2001469"},"menu":{"hasChildren":false},"tocID":"id_2001469-d46e305075","topics":[]},{"title":"Applying LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Apply LOTO to both the gradient and system Power Distribution Unit (PDU) breakers on the MDP when servicing either of these items in the ISC. Apply LOTO to make sure of a safe environment when working on these parts.<\/p>","href":"t_Applying-LOTO-ISC_78.html","attributes":{"data-id":"id_2001781"},"menu":{"hasChildren":false},"tocID":"id_2001781-d46e305179","topics":[]},{"title":"Removing the rear bridge cover","shortdesc":"<p class=\"shortdesc\">Removes the table rear bridge cover from the magnet enclosure.<\/p>","href":"t_RemovingTheFixedTableRearBridgeCover_25.html","attributes":{"data-id":"id_2002974"},"menu":{"hasChildren":false},"tocID":"id_2002974-d46e305283","topics":[]},{"title":"Removing the rear bridge inner cover","shortdesc":"<p class=\"shortdesc\">Removes the rear bridge inner cover from the magnet enclosure.<\/p>","href":"t_RemovingTheRearBridgeInnerCover_23.html","attributes":{"data-id":"id_2002976"},"menu":{"hasChildren":false},"tocID":"id_2002976-d46e305387","topics":[]},{"title":"Removing the heat exchanger temperature sensor","shortdesc":"<p class=\"shortdesc\">Removes the temperature sensor from the heat exchanger.<\/p>","href":"t_RemovingTheHeatExchangerTemperatureSensor.html","attributes":{"data-id":"id_2005722"},"menu":{"hasChildren":false},"tocID":"id_2005722-d46e305491","topics":[]},{"title":"Installing the heat exchanger temperature sensor","href":"t_InstallingTheHeatExchangerTemperatureSensor.html","attributes":{"data-id":"id_2005723"},"menu":{"hasChildren":false},"tocID":"id_2005723-d46e305595","topics":[]},{"title":"Installing the rear bridge inner cover","shortdesc":"<p class=\"shortdesc\">Installs the rear bridge inner cover onto the magnet enclosure.<\/p>","href":"t_InstallingTheRearBridgeInnerCover_23.html","attributes":{"data-id":"id_2002977"},"menu":{"hasChildren":false},"tocID":"id_2002977-d46e305696","topics":[]},{"title":"Installing the rear bridge cover","shortdesc":"<p class=\"shortdesc\">Installs the table rear bridge cover onto the magnet enclosure.<\/p>","href":"t_InstallingTheFixedTableRearBridgeCover_25.html","attributes":{"data-id":"id_2002975"},"menu":{"hasChildren":false},"tocID":"id_2002975-d46e305800","topics":[]},{"title":"Removing LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Remove LOTO from the gradient and system PDU breakers on the MDP before restoring power to the ISC.<\/p>","href":"t_Removing-LOTO-ISC_80.html","attributes":{"data-id":"id_2001783"},"menu":{"hasChildren":false},"tocID":"id_2001783-d46e305904","topics":[]},{"title":"Starting up the host computer","shortdesc":"<p class=\"shortdesc\">How to start the host computer.<\/p>","href":"t_StartingUpTheHostComputer_86.html","attributes":{"data-id":"id_2001468"},"menu":{"hasChildren":false},"tocID":"id_2001468-d46e306010","topics":[]},{"title":"Doing a check scan","shortdesc":"<p class=\"shortdesc\"> A check scan is done at the conclusion of many procedures. This functional check assures the unit is in good clinical working order.<\/p>","href":"t_DoingACheckScan_108.html","attributes":{"data-id":"id_2001754"},"menu":{"hasChildren":false},"tocID":"id_2001754-d46e306114","topics":[]}]});